#!/usr/bin/env python3
"""FC3D refreshed v1.101 baseline, revision v1.128.

Based directly on v1.122 plumbing and v1.101 optical field, but replaces the
single 0.14-mm road with a 0.14-mm 3->2->1 stepped stack.  v1.128 extends the cut-independent mathematical recurrence to finite bead
geometry: 0.400-mm-wide roads on exactly 0.400-mm centres, including the full
3/2/1 tier envelopes.  Shadow is cast from the outer physical edge of the top
bead to the next bottom plane; bottom/middle/top non-overlap constraints are
solved explicitly. Tile clipping remains downstream of the recurrence.

Requires only canonical 3dprintv1.179.py beside this script (or --source path).
"""
from __future__ import annotations
import argparse, base64, hashlib, json, math, re, sys, tempfile, types, zipfile, zlib
from pathlib import Path

