def _v128_shadow_pitch_at_frame(fr, tier_h=0.100):
    """Top optical inner edge -> next bottom-tier plane shadow pitch.

    The top inner edge is 2*du outward from the bottom inner edge and is
    2*tier_h above the next bottom-tier Z plane.  `projector_unit` points from
    the screen toward the projector, so the light ray continuing away from the
    projector drops by 2*tier_h while advancing by the projected ray run.
    """
    theta=max(1e-6,math.radians(fr['facet_tilt_deg']))
    du=float(tier_h)/max(1e-9,math.tan(theta))
    pu=fr['projector_unit'][0]*fr['b_unit'][0]+fr['projector_unit'][1]*fr['b_unit'][1]
    pz=fr['projector_unit'][2]
    ray_run=2.0*float(tier_h)*abs(pu)/max(1e-9,abs(pz))
    pitch=2.0*du + ray_run
    return pitch,du,ray_run


def _v128_math_stack_plan(rt, piece, clip_piece=None, max_slots=400):
    """Build the v1.128 shadow-spaced inner-edge recurrence before clipping.

    `piece` establishes the mathematical starting arc. `clip_piece` is used
    only to observe the finished curve intersection and never affects pitch.
    """
    clip_piece = piece if clip_piece is None else clip_piece
    curve=rt._waveset_outer_reference_curve(piece)
    plans=[]; cumulative=0.0; seen=False; empty_after=0
    for slot in range(int(max_slots)):
        vals=[]; dus=[]; ray_runs=[]
        for x,z in curve:
            pitch,du,ray_run=_v128_shadow_pitch_at_frame(rt.mirror_frame_global(x,z))
            vals.append(pitch); dus.append(du); ray_runs.append(ray_run)
        # One complete curved stack must clear its shadow everywhere along the arc.
        req=max(vals) if vals else 0.0
        clipped=rt._waveset_clip_curve(curve,clip_piece)
        plans.append({'slot':slot,'curve':curve,'math_distance_mm':cumulative,
                      'math_spacing_mm':0.0 if slot==0 else plans[-1]['required_pitch_mm'],
                      'required_pitch_mm':req,'shadow_pitch_max_mm':req,
                      'du_min_mm':min(dus) if dus else 0.0,
                      'du_max_mm':max(dus) if dus else 0.0,
                      'ray_run_min_mm':min(ray_runs) if ray_runs else 0.0,
                      'ray_run_max_mm':max(ray_runs) if ray_runs else 0.0,
                      'clipped_inner':clipped})
        if clipped:
            seen=True; empty_after=0
        elif seen:
            empty_after += 1
            if empty_after >= 4:
                break
        curve=rt._waveset_advance_curve_inward(curve,req)
        cumulative += req
    return plans

V128_EMITTER_SOURCE='def _v128_pitch_terms(du_current, du_next, ray_run, road_w=0.400, road_pitch=0.400):\n    """Finite-width 3->2->1 pitch constraints for one local cross-section.\n\n    U is the physical inner edge of the bottom triple.  The top single occupies\n    [U+2*du, U+2*du+road_w], so its OUTER physical edge is the shadow origin.\n    Adjacent roads, including across stack boundaries, are road_pitch apart by\n    centreline.  Returns each independent required stack-to-stack pitch.\n    """\n    shadow = 2.0*du_current + road_w + ray_run\n    bottom = 3.0*road_pitch\n    middle = 2.0*road_pitch + du_current - du_next\n    top = road_pitch + 2.0*(du_current-du_next)\n    constraints = {\'shadow\':shadow, \'bottom\':bottom, \'middle\':middle, \'top\':top}\n    limiting = max(constraints, key=constraints.get)\n    return {**constraints, \'pitch\':constraints[limiting], \'limiting\':limiting}\n\n\ndef _v128_outer_reference_curve(piece):\n    """Return the same mathematical outer reference arc as v1.128, but retain\n    enough of its uncut master contour that advancing the lattice across the\n    tile cannot run out of tangent extent before final clipping.\n\n    This affects only field coverage.  It does not participate in stack pitch,\n    shadow, tier offset, or any other optical-spacing calculation.\n    """\n    lat=get_mirror_wave_lattice(piece)\n    candidates=[]\n    for rec in lat["main_a_curves"]:\n        clips=_clip_polyline2_to_piece(rec["points"],piece)\n        if not clips:\n            continue\n        pts=clips[0]\n        rr=[math.hypot(x-MASTER_FAN.projector_x_mm,z-MASTER_FAN.projector_z_mm) for x,z in pts]\n        candidates.append((sum(rr)/len(rr),rec))\n    if not candidates:\n        raise RuntimeError(f"{piece.name}: no v1.101 outer reference arc")\n    full=[(float(x),float(z)) for x,z in max(candidates,key=lambda q:q[0])[1]["points"]]\n    # At least half the larger tile dimension beyond every edge.  This is an\n    # arc-length/coverage halo only; the mathematical normal spacing remains\n    # entirely controlled by solve_required_pitch().\n    field_halo=0.50*max(piece.global_x1_mm-piece.global_x0_mm,\n                        piece.global_z1_mm-piece.global_z0_mm)\n    idx=[i for i,(x,z) in enumerate(full)\n         if piece.global_x0_mm-field_halo <= x <= piece.global_x1_mm+field_halo\n         and piece.global_z0_mm-field_halo <= z <= piece.global_z1_mm+field_halo]\n    if not idx:\n        raise RuntimeError(f"{piece.name}: outer reference has no field-halo samples")\n    a=max(0,min(idx)-2); b=min(len(full),max(idx)+3)\n    return _resample_polyline2(full[a:b],1.0)\n\n\ndef _explicit_mirror_wave_layer_gcode(piece: PieceSpec, x_origin: float, y_origin: float):\n    """v1.128 finite-width top-shadow 3->2->1 lattice; clipping happens last."""\n    E_PER_MM=0.021938\n    ROAD_W=0.400\n    ROAD_PITCH=0.400\n    TIER_H=0.140\n    BASE_FOOTPRINT=2.0*ROAD_PITCH + ROAD_W\n    DRY=0.160; REPRIME=0.795; RETRACT=0.800\n    FEED=A_PRINT_FEED_MM_S*60.0\n    base_top=BASE_TOP_Z_MM; travel_z=base_top+3.0*TIER_H+0.200\n    xo=float(x_origin); yo=float(y_origin)\n\n    def point_ray_and_du_global(p):\n        fr=mirror_frame_global(p[0],p[1])\n        theta=max(1e-6,math.radians(fr[\'facet_tilt_deg\']))\n        du=TIER_H/max(1e-9,math.tan(theta))\n        pu=fr[\'projector_unit\'][0]*fr[\'b_unit\'][0]+fr[\'projector_unit\'][1]*fr[\'b_unit\'][1]\n        pz=fr[\'projector_unit\'][2]\n        ray_run=2.0*TIER_H*abs(pu)/max(1e-9,abs(pz))\n        return du,ray_run,fr\n\n    def solve_required_pitch(curve):\n        cur=[point_ray_and_du_global(p) for p in curve]\n        if not cur:\n            return 0.0, {\'shadow\':0.0,\'bottom\':BASE_FOOTPRINT,\'middle\':0.0,\'top\':0.0}, \'bottom\'\n        shadow=max(2.0*du + ROAD_W + ray for du,ray,fr in cur)\n        pitch=max(BASE_FOOTPRINT,shadow)\n        # d(next) depends weakly on the position implied by pitch, so solve that\n        # finite-envelope coupling rather than assuming the same d for both stacks.\n        for _ in range(12):\n            nxt_curve=_waveset_advance_curve_inward(curve,pitch)\n            nxt=[point_ray_and_du_global(p) for p in nxt_curve]\n            n=min(len(cur),len(nxt))\n            if n:\n                middle=max(2.0*ROAD_PITCH + cur[i][0] - nxt[i][0] for i in range(n))\n                top=max(ROAD_PITCH + 2.0*(cur[i][0]-nxt[i][0]) for i in range(n))\n            else:\n                middle=2.0*ROAD_PITCH; top=ROAD_PITCH\n            terms={\'shadow\':shadow,\'bottom\':3.0*ROAD_PITCH,\'middle\':middle,\'top\':top}\n            new_pitch=max(terms.values())\n            if abs(new_pitch-pitch)<1e-10:\n                pitch=new_pitch; break\n            pitch=new_pitch\n        limiting=max(terms,key=terms.get)\n        return pitch,terms,limiting\n\n    # MATHEMATICAL FINITE-WIDTH RECURRENCE FIRST. No clipped coordinate participates.\n    curve=_v128_outer_reference_curve(piece)\n    math_slots=[]; cumulative=0.0; seen=False; empty_after=0\n    for slot in range(400):\n        req,terms,limiting=solve_required_pitch(curve)\n        vals=[point_ray_and_du_global(p) for p in curve]\n        ray_min=min(v[1] for v in vals) if vals else 0.0\n        ray_max=max(v[1] for v in vals) if vals else 0.0\n        inner_clip=_waveset_clip_curve(curve,piece)\n        math_slots.append((slot,cumulative,curve,req,terms,limiting,ray_min,ray_max,inner_clip))\n        if inner_clip:\n            seen=True; empty_after=0\n        elif seen:\n            empty_after += 1\n            if empty_after>=4: break\n        curve=_waveset_advance_curve_inward(curve,req)\n        cumulative += req\n\n    def offset_curve_global(curve,tier,road_idx):\n        out=[]\n        for p in curve:\n            du,ray_run,fr=point_ray_and_du_global(p)\n            u_inner=(0.0,du,2.0*du)[tier]\n            off=u_inner + ROAD_W/2.0 + road_idx*ROAD_PITCH\n            bu=fr[\'b_unit\']\n            out.append((p[0]+bu[0]*off,p[1]+bu[1]*off))\n        return out\n\n    def clipped_local(curve,tier,road_idx):\n        c=_waveset_clip_curve(offset_curve_global(curve,tier,road_idx),piece)\n        return [(p[0]-piece.global_x0_mm,p[1]-piece.global_z0_mm) for p in c]\n\n    printable=[]\n    for slot,cum,curve,req,terms,limiting,ray_min,ray_max,inner_clip in math_slots:\n        roads={(tier,ri):clipped_local(curve,tier,ri)\n               for tier,count in ((0,3),(1,2),(2,1)) for ri in range(count)}\n        if all(len(v)>=2 for v in roads.values()):\n            printable.append((slot,cum,curve,req,terms,limiting,ray_min,ray_max,roads))\n\n    def lengths(pts):\n        seg=[math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(pts,pts[1:])]\n        return seg,sum(seg)\n\n    rows=[]\n    rows.append(f\'; FC3D_V1128_A_ONLY_START math_slots={len(math_slots)} printable_stacks={len(printable)} road_w={ROAD_W:.3f} road_pitch={ROAD_PITCH:.3f} base_footprint={BASE_FOOTPRINT:.3f} spacing_rule=finite_bead_top_shadow_plus_tier_nonoverlap\')\n    prev_cum=None\n    for pi,(slot,cum,curve,req,terms,limiting,ray_min,ray_max,roads) in enumerate(printable,1):\n        dus=[]; tilts=[]\n        for p in curve:\n            du,ray_run,fr=point_ray_and_du_global(p); dus.append(du); tilts.append(fr[\'facet_tilt_deg\'])\n        spacing=0.0 if prev_cum is None else cum-prev_cum\n        rows.append(f\'; FC3D_V1128_STACK_PLAN stack={pi} math_slot={slot} math_u={cum:.6f} prev_printed_spacing={spacing:.6f} required_pitch={req:.6f} limit={limiting} shadow_req={terms["shadow"]:.6f} bottom_req={terms["bottom"]:.6f} middle_req={terms["middle"]:.6f} top_req={terms["top"]:.6f} ray_run_min={ray_min:.6f} ray_run_max={ray_max:.6f} du_min={min(dus):.6f} du_max={max(dus):.6f} tilt_min={min(tilts):.4f} tilt_max={max(tilts):.4f}\')\n        prev_cum=cum\n    road_seq=0\n    for tier,count in ((0,3),(1,2),(2,1)):\n        z_abs=base_top+(tier+1)*TIER_H\n        rows.append(f\'; FC3D_V1128_TIER_START tier={tier+1} roads_per_stack={count} z={z_abs:.3f}\')\n        for si,(slot,cum,curve,req,terms,limiting,ray_min,ray_max,roads) in enumerate(printable,1):\n            for ri in range(count):\n                pts=roads[(tier,ri)]\n                seg,total=lengths(pts)\n                if total<=DRY+1e-6: continue\n                road_seq+=1; draw_len=total-DRY\n                rows.append(f\'; FC3D_V1128_STACK_ROAD_START road={road_seq} stack={si} math_slot={slot} tier={tier+1} tier_road={ri+1} z={z_abs:.3f}\')\n                rows.append(f\'G0 Z{travel_z:.3f} F900 ; FC3D_V1128_STACK_TRAVEL_Z\')\n                rows.append(f\'G0 X{xo+pts[0][0]:.3f} Y{yo+pts[0][1]:.3f} F18000 ; FC3D_V1128_STACK_MOVE\')\n                rows.append(f\'G0 Z{z_abs:.3f} F900 ; FC3D_V1128_STACK_HEIGHT\')\n                rows.append(f\'G1 E{REPRIME:.3f} F1800 ; FC3D_V1128_STACK_REPRIME\')\n                remain=draw_len; a=pts[0]\n                for j,(b,ds) in enumerate(zip(pts[1:],seg)):\n                    if remain<=1e-12: break\n                    use=min(ds,remain)\n                    if ds<=1e-12: continue\n                    if use<ds-1e-12:\n                        t=use/ds; q=(a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1]))\n                    else: q=b\n                    e=use*E_PER_MM\n                    if round(e,5)>0:\n                        rows.append(f\'G1 X{xo+q[0]:.3f} Y{yo+q[1]:.3f} Z{z_abs:.3f} E{e:.5f} F{FEED:.0f} ; FC3D_V1128_STACK_SEG stack={si} tier={tier+1} tier_road={ri+1} seg={j}\')\n                    remain-=use; a=q\n                    if use<ds-1e-12: break\n                rows.append(f\'G1 E-{RETRACT:.3f} F1800 ; FC3D_V1128_STACK_RETRACT\')\n                rows.append(f\'G1 X{xo+pts[-1][0]:.3f} Y{yo+pts[-1][1]:.3f} Z{z_abs:.3f} F15000 ; FC3D_V1128_STACK_DRY_TAIL len={DRY:.3f}\')\n                rows.append(f\'; FC3D_V1128_STACK_ROAD_END road={road_seq} stack={si} math_slot={slot} tier={tier+1} tier_road={ri+1}\')\n        rows.append(f\'; FC3D_V1128_TIER_END tier={tier+1}\')\n    rows.append(f\'G0 Z{travel_z:.3f} F900 ; FC3D_V1128_OPTICAL_SAFE_END_Z\')\n    rows.append(f\'; FC3D_V1128_A_ONLY_END printable_stacks={len(printable)} emitted_roads={road_seq}\')\n    return rows\n'

