def _load_runtime():
    src=zlib.decompress(base64.b64decode(EMBEDDED_V106_B64)).decode('utf-8')
    mod=types.ModuleType('fc3d_v128_runtime')
    mod.__file__=__file__
    sys.modules[mod.__name__]=mod
    exec(compile(src,'<embedded-v106-plumbing>','exec'),mod.__dict__)
    # Release identity and physical rear label are v1.128.
    mod.SCRIPT_VERSION=SCRIPT_VERSION
    mod.REAR_VERSION_TEXT=REAR_VERSION_TEXT
    # Reinstall the exact v1.101 single-main optical emitter over the v1.106 wave emitter.
    exec(compile(V128_EMITTER_SOURCE,'<v128-stepped-stack-emitter>','exec'),mod.__dict__)
    return mod

def _replace_zip(output:Path,repl:dict[str,bytes]):
    output=Path(output)
    with zipfile.ZipFile(output,'r') as zin:
        infos=zin.infolist(); data={i.filename:zin.read(i.filename) for i in infos}
    data.update(repl)
    tmp=output.with_suffix(output.suffix+'.v122tmp')
    with zipfile.ZipFile(tmp,'w') as zout:
        for i in infos:
            zout.writestr(i,data[i.filename])
    tmp.replace(output)

def _patch_native_lifecycle_and_revision(output:Path):
    output=Path(output)
    with zipfile.ZipFile(output,'r') as z:
        gb=z.read('Metadata/plate_1.gcode'); g=gb.decode('utf-8','strict')
        project=json.loads(z.read('Metadata/project_settings.config').decode('utf-8'))
    # Replace compact inherited startup.
    ex0=g.find('; EXECUTABLE_BLOCK_START')
    ex1=g.find('; EXECUTABLE_BLOCK_END',ex0+1)
    if ex0 < 0 or ex1 < 0: raise RuntimeError(f'{SCRIPT_VERSION}: executable block missing')
    sb=g.find('; FC3D_V1106_A1MINI_START',ex0,ex1)
    se=g.find('; FC3D_V1106_A1MINI_START_END',sb,ex1)
    if sb<0 or se<0: raise RuntimeError(f'{SCRIPT_VERSION}: compact startup block not found')
    se2=g.find('\n',se); se2=len(g) if se2<0 else se2+1
    g=g[:sb]+_native_start_v122()+'\n'+g[se2:]
    # Replace compact inherited end with complete native lifecycle.
    model_end=g.rfind('; V4_MODEL_END')
    ex1=g.find('; EXECUTABLE_BLOCK_END',model_end)
    eb=g.find('; FC3D_V1106_A1MINI_END',model_end,ex1)
    ee=g.find('; FC3D_V1106_A1MINI_END_DONE',eb,ex1)
    if eb<0 or ee<0: raise RuntimeError(f'{SCRIPT_VERSION}: compact end block not found')
    ee2=g.find('\n',ee); ee2=len(g) if ee2<0 else ee2+1
    # v1.128 optical peak is support Z0.400 + 3 x 0.140 = 0.820 mm.
    g=g[:eb]+_native_end_v122(0.820,90.0)+'\n'+g[ee2:]
    # Advance inherited executable markers/comments only after all inherited operations complete.
    g=g.replace('FC3D_V1106','FC3D_V1128').replace('V1.106','V1.128').replace('v1.106','v1.128')
    # Project config should describe the same lifecycle visible in executable G-code.
    project['machine_start_gcode']=_native_start_v122()
    project['machine_end_gcode']=_native_end_v122(0.820,90.0)+'\n'
    newb=g.encode('utf-8')
    _replace_zip(output,{
        'Metadata/plate_1.gcode':newb,
        'Metadata/plate_1.gcode.md5':(hashlib.md5(newb).hexdigest()+'\n').encode('ascii'),
        'Metadata/project_settings.config':json.dumps(project,separators=(',',':')).encode('utf-8'),
    })

def _audit_refresh(output:Path):
    output=Path(output)
    with zipfile.ZipFile(output,'r') as z:
        assert z.testzip() is None
        gb=z.read('Metadata/plate_1.gcode'); g=gb.decode('utf-8','strict')
        md5=z.read('Metadata/plate_1.gcode.md5').decode('ascii').strip().lower()
    if md5!=hashlib.md5(gb).hexdigest(): raise RuntimeError(f'{SCRIPT_VERSION}: MD5 mismatch')
    ex0=g.find('; EXECUTABLE_BLOCK_START'); s0=g.find('; FC3D_V1128_A1MINI_START',ex0); s1=g.find('; FC3D_V1128_A1MINI_START_END',s0)
    if min(ex0,s0,s1)<0: raise RuntimeError(f'{SCRIPT_VERSION}: native startup markers missing')
    startup=g[s0:s1]
    for tok in ('M620 M','M620 S0A','T0','M621 S0A',';===== nozzle load line',';===== extrude cali test'):
        if tok not in startup: raise RuntimeError(f'{SCRIPT_VERSION}: startup missing {tok}')
    tail=g[g.rfind('; V4_MODEL_END'):]
    for tok in ('FC3D_V1128_A1MINI_NATIVE_END_BEGIN','M620 S255','T255','M621 S255','M140 S0','M104 S0','M18 X Y Z','FC3D_V1128_A1MINI_NATIVE_END_DONE'):
        if tok not in tail: raise RuntimeError(f'{SCRIPT_VERSION}: native end missing {tok}')
    block=g[g.find('; FC3D_V1128_MIRROR_WAVE_START'):g.find('; FC3D_V1128_MIRROR_WAVE_END')]
    plans=[l for l in block.splitlines() if 'FC3D_V1128_STACK_PLAN' in l]
    starts=[l for l in block.splitlines() if 'FC3D_V1128_STACK_ROAD_START' in l]
    reps=block.count('FC3D_V1128_STACK_REPRIME'); rets=block.count('FC3D_V1128_STACK_RETRACT'); ends=block.count('FC3D_V1128_STACK_ROAD_END')
    if not plans or not starts: raise RuntimeError(f'{SCRIPT_VERSION}: stepped stack absent')
    if not (len(starts)==reps==rets==ends): raise RuntimeError(f'{SCRIPT_VERSION}: pressure cycle mismatch')
    tier_counts={t:sum(f'tier={t} ' in l for l in starts) for t in (1,2,3)}
    stacks=len(plans)
    if tier_counts != {1:3*stacks,2:2*stacks,3:stacks}: raise RuntimeError(f'{SCRIPT_VERSION}: incomplete printable stack survived {tier_counts}/{stacks}')
    segs=[l for l in block.splitlines() if 'FC3D_V1128_STACK_SEG' in l]
    xre=re.compile(r'\bX([-+0-9.]+)'); yre=re.compile(r'\bY([-+0-9.]+)'); ere=re.compile(r'\bE([-+0-9.]+)')
    epm=[]
    for rb in re.findall(r'; FC3D_V1128_STACK_ROAD_START.*?; FC3D_V1128_STACK_ROAD_END[^\n]*',block,re.S):
        move=next(l for l in rb.splitlines() if 'STACK_MOVE' in l); pos=(float(xre.search(move).group(1)),float(yre.search(move).group(1)))
        for l in rb.splitlines():
            if 'STACK_SEG' not in l: continue
            x=float(xre.search(l).group(1)); y=float(yre.search(l).group(1)); e=float(ere.search(l).group(1)); d=math.hypot(x-pos[0],y-pos[1])
            if d>1e-9: epm.append(e/d)
            pos=(x,y)
    mean_epm=sum(epm)/len(epm)
    if abs(mean_epm-0.021938)>8e-5: raise RuntimeError(f'{SCRIPT_VERSION}: 0.14 road E/mm {mean_epm:.8f}')
    if 'TOP_VALLEY_FILL_DRAW' in g: raise RuntimeError(f'{SCRIPT_VERSION}: incompatible v1.122 valley filler survived')
    fre=lambda key,l: float(re.search(key+r'=([-+0-9.]+)',l).group(1))
    ire=lambda key,l: int(re.search(key+r'=([0-9]+)',l).group(1))
    slots=[]; math_u=[]; pitches=[]; printed_sp=[]; shadows=[]; dus=[]; tilts=[]; shadow_req=[]; bottom_req=[]; middle_req=[]; top_req=[]; limits=[]
    for l in plans:
        slots.append(ire('math_slot',l)); math_u.append(fre('math_u',l)); pitches.append(fre('required_pitch',l)); printed_sp.append(fre('prev_printed_spacing',l)); shadows.append(fre('ray_run_max',l)); dus += [fre('du_min',l),fre('du_max',l)]; tilts += [fre('tilt_min',l),fre('tilt_max',l)]; shadow_req.append(fre('shadow_req',l)); bottom_req.append(fre('bottom_req',l)); middle_req.append(fre('middle_req',l)); top_req.append(fre('top_req',l)); limits.append(re.search(r'\blimit=([a-z]+)',l).group(1))
    # Every mathematical slot interval represented between consecutive printable slots
    # must be exactly the sum of the recurrence pitches; tile clipping may skip an edge
    # slot but may never alter the recurrence.
    for i in range(1,len(plans)):
        actual=math_u[i]-math_u[i-1]
        if abs(actual-printed_sp[i])>3e-6: raise RuntimeError(f'{SCRIPT_VERSION}: printed spacing audit mismatch {actual} vs {printed_sp[i]}')
    if min(pitches)<=0.0: raise RuntimeError(f'{SCRIPT_VERSION}: non-positive finite-width pitch')
    if abs(min(bottom_req)-1.2)>1e-6 or abs(max(bottom_req)-1.2)>1e-6: raise RuntimeError(f'{SCRIPT_VERSION}: bottom 3-road constraint is not 1.200 mm')
    for p,sr,br,mr,tr in zip(pitches,shadow_req,bottom_req,middle_req,top_req):
        if abs(p-max(sr,br,mr,tr))>3e-6: raise RuntimeError(f'{SCRIPT_VERSION}: pitch is not max of finite-width constraints')
    return {'math_slots':max(slots)+1 if slots else 0,'selected_stacks':stacks,'emitted_roads':len(starts),'tier1_roads':tier_counts[1],'tier2_roads':tier_counts[2],'tier3_roads':tier_counts[3],'segments':len(segs),'mean_e_per_mm':mean_epm,'math_pitch_min':min(pitches),'math_pitch_max':max(pitches),'printed_spacing_min':min(x for x in printed_sp if x>0),'printed_spacing_max':max(printed_sp),'ray_run_max':max(shadows),'shadow_req_min':min(shadow_req),'shadow_req_max':max(shadow_req),'bottom_req':max(bottom_req),'middle_req_max':max(middle_req),'top_req_max':max(top_req),'limiting_constraints':','.join(sorted(set(limits))),'du_min':min(dus),'du_max':max(dus),'tilt_min':min(tilts),'tilt_max':max(tilts),'startup':'PASS','end':'PASS','cut_independence':'PASS'}

def main():
    ap=argparse.ArgumentParser(description='FC3D v1.128 0.14-mm-tier finite-width top-shadow-spaced 3-2-1 optical stack with full-card field coverage',allow_abbrev=False)
    ap.add_argument('--source',type=Path,default=Path('3dprintv1.179.py'))
    ap.add_argument('--piece',choices=tuple(f'{c}-{r}' for c in range(1,6) for r in range(1,6)),required=True)
    ap.add_argument('--output',type=Path)
    ap.add_argument('--dry-validate',action='store_true')
    ap.add_argument('--slicer-target','--slicer',choices=('orca','studio'),default='orca')
    known,passthrough=ap.parse_known_args()
    if known.output is None: known.output=Path(f"black_a_only_3to2to1_0p14_finitewidth_topshadow_fullfield_{known.piece.replace('-','_')}_v1.128.gcode.3mf")
    rt=_load_runtime()
    rt.reject_protected_passthrough(passthrough)
    rt.CURRENT_PIECE=rt.PieceSpec.for_name(known.piece); rt.RUNTIME_ORIGIN=None
    rt.set_runtime_e_per_mm(rt.DEFAULT_E_PER_MM)
    # Guard the source-of-truth constants before doing any expensive generation.
    lat=rt.get_mirror_wave_lattice(rt.CURRENT_PIECE)
    if len(lat['main_a_local'])!=V101_ROADS: raise RuntimeError(f'{SCRIPT_VERSION}: v1.101 lattice road count {len(lat["main_a_local"])} != 251')
    print(SCRIPT_VERSION)
    print('  optical stack                 : fixed 3-road base -> shifted 2-road -> shifted 1-road')
    print('  tier height / road dose       : 0.140 mm / 0.021938 E/mm')
    print('  packing                       : exact mathematical inner-edge recurrence; clipping applied last')
    print('  road geometry                 : 0.400-mm bead width / exactly 0.400-mm road-centre pitch')
    print('  mathematical pitch            : max(top-outer-edge shadow, bottom/middle/top finite-width non-overlap)')
    print('  legacy valley fill            : omitted for stepped-stack isolation test')
    print('  rear version                  :',REAR_VERSION_TEXT)
    if known.dry_validate:
        print('DRY V1.128 FULL-FIELD FINITE-WIDTH STEPPED-STACK VALIDATION: PASS')
        return
    dp=rt.import_3dprint(known.source); rt.install_patches(dp,45.0,45.0,45.0)
    # install_patches can overwrite runtime globals; reassert refreshed-baseline identity/emitter.
    rt.REAR_VERSION_TEXT=REAR_VERSION_TEXT; rt.SCRIPT_VERSION=SCRIPT_VERSION
    exec(compile(V128_EMITTER_SOURCE,'<v128-stepped-stack-emitter>','exec'),rt.__dict__)
    with tempfile.TemporaryDirectory(prefix='fc3d_v128_') as td:
        from PIL import Image
        placeholder=Path(td)/'placeholder.png'; Image.new('RGB',(8,2),(22,22,22)).save(placeholder)
        base_args=[str(known.source),'--direct-layer-images',','.join([str(placeholder)]*rt.DIRECT_OPTICAL_LAYER_COUNT),'--direct-layout','4x2','--center-x','90.000','--center-y','90.000','--output',str(known.output),'--rp-pitch-mm',f'{rt.RP_PITCH_MM:.6f}','--print-width-mm',f'{rt.ROAD_WIDTH_MM:.6f}','--endpoint-trim-mm','0','--close-gaps-mm','0','--directional-block-mm','0','--edge-aa','off','--skip-absent-layer-materials','on','--progress','on','--filament-assignment-json',json.dumps({rt.LOGICAL_MATERIAL:rt.BLACK_ASSIGNMENT},separators=(',',':'))]
        old=sys.argv
        try: sys.argv=base_args+list(passthrough); dp.main()
        finally: sys.argv=old
    # Apply only the known-good physical plumbing shared with the old baseline.
    rt.apply_mirror_wave_paths(known.output)
    rt.apply_dynamic_tower_policy(known.output)
    rt.enforce_minimum_model_part_fan(known.output)
    rt.audit_final_base_interlock(known.output)
    rt.audit_final_black_texture_and_single_material(known.output)
    rt.convert_package_to_a1mini_orca(known.output)
    rt.normalize_a1mini_orca_reference_metadata(known.output)
    rt.apply_slicer_target_metadata(known.output,known.slicer_target)
    _patch_native_lifecycle_and_revision(known.output)
    rep=_audit_refresh(known.output)
    print('\nFINAL V1.128 FULL-FIELD FINITE-WIDTH TOP-SHADOW 3-2-1 AUDIT: PASS')
    for k,v in rep.items(): print(f'  {k:28s} : {v}')
    print('Wrote',known.output)

if __name__=='__main__': main()
